import itertools
import json

def solve_puzzle():
    # Input variables (puzzle parameters)
    houses = [1, 2]  # numbered left to right
    names = ["Eric", "Arnold"]
    sports = ["basketball", "soccer"]
    hobbies = ["photography", "gardening"]

    solutions = []

    # Enumerate all bijective assignments via permutations
    for names_perm in itertools.permutations(names):
        for sports_perm in itertools.permutations(sports):
            for hobbies_perm in itertools.permutations(hobbies):
                # Build assignment: house -> attributes
                assignment = {}
                for idx, h in enumerate(houses):
                    assignment[h] = {
                        "Name": names_perm[idx],
                        "FavoriteSport": sports_perm[idx],
                        "Hobby": hobbies_perm[idx],
                    }

                # Apply constraints

                # 1. The person who enjoys gardening is Arnold.
                gardener_houses = [h for h in houses if assignment[h]["Hobby"] == "gardening"]
                if len(gardener_houses) != 1:
                    continue
                gardener_house = gardener_houses[0]
                if assignment[gardener_house]["Name"] != "Arnold":
                    continue

                # 2. The photography enthusiast is not in the first house.
                if assignment[1]["Hobby"] == "photography":
                    continue

                # 3. The person who loves soccer is not in the first house.
                if assignment[1]["FavoriteSport"] == "soccer":
                    continue

                # If all constraints satisfied, store solution
                solutions.append(assignment)

    # Choose the first (should be unique for well-posed puzzle)
    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")
    solution = solutions[0]

    # Prepare output in required JSON structure
    output = {
        "solution": {
            "header": ["House", "Name", "FavoriteSport", "Hobby"],
            "rows": [
                [str(h), solution[h]["Name"], solution[h]["FavoriteSport"], solution[h]["Hobby"]]
                for h in sorted(houses)
            ],
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
